using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
public partial class CommonMechanicsSuite {
 GameObject Fixture(Vector3 center,Vector3 size){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name="Capture-only movement platform";o.transform.position=center;o.transform.localScale=size;o.GetComponent<Renderer>().sharedMaterial=GameAssets.I.buildPrefabs[1].GetComponentInChildren<Renderer>().sharedMaterial;Physics.SyncTransforms();return o;}
 IEnumerator Advanced(){
  if(filter!=null&&filter.StartsWith("results")){yield return Results();yield break;}
  if(Need("fall_damage")){var parts=new List<string>();for(int water=0;water<2;water++){string id="fall_damage__"+(water==0?"land":"water");parts.Add(id);if(Done(id))continue;var at=water==0?site:FindWater();Stage(at);float y=Ground(at);if(water==1&&Water.Surface(at,out var wy))y=wy;var platform=Fixture(new Vector3(at.x,y+8,at.z),new Vector3(5,.4f,5));pc.Teleport(new Vector3(at.x,y+8.3f,at.z),0);_look=Feet+Vector3.forward*40;yield return Wait(2);yield return Take(id,water==0?"Fall onto land":"Fall into deep water",FallTake(),"An eight-metre presentation platform is prepared before capture. Falling and damage use the ordinary movement controller.");Destroy(platform);yield return null;}MechanicsTopicJoin.Write(root,"fall_damage","Fall / land damage and deep-water landing",model,parts.ToArray());}
  if(Need("building_controls")){foreach(var d in Destructible.Built.ToArray())if(d)Destroy(d.gameObject);yield return null;BuildSystem.Reset();Stage(site);pc.me.inv.mats[0]=20;pc.me.inv.mats[1]=pc.me.inv.mats[2]=0;yield return Wait(1);yield return Take("building_controls","Build orientation / hold placement / material limit",BuildControlsTake(),"This implementation rotates placement by view direction. There is no independent rotate input. Two pieces worth of material are prepared before capture.");}
 }
 IEnumerator FallTake(){step="Platform / full health";yield return Wait(3);step="Walk off the edge";_move=Vector2.up;yield return Wait(2.8f);_move=Vector2.zero;step="Landing and health result";yield return Wait(6);_move=new Vector2(.3f,0);yield return Wait(2);_move=Vector2.zero;yield return Wait(3);}
 IEnumerator BuildControlsTake(){_build=2;yield return Wait(2);step="Preview orientation follows view";for(int i=0;i<4;i++){_look=Feet+Quaternion.Euler(0,i*90,0)*Vector3.forward*25+Vector3.up;yield return Wait(3);}step="Floor / hold to place";_look=Feet+Vector3.forward*30+Vector3.up;_build=1;yield return Wait(2);_hold=true;_move=new Vector2(.5f,0);yield return Wait(6);_move=Vector2.zero;_hold=false;step="Not enough material / blocked placement";_tap=true;yield return Wait(5);_slot=0;yield return Wait(4);}
 IEnumerator RecordEdits(){var parts=new List<string>();for(int shape=0;shape<2;shape++){string id="editing__"+(shape==0?"wall":"floor");parts.Add(id);if(Done(id))continue;foreach(var old in Destructible.Built.ToArray())if(old)Destroy(old.gameObject);yield return null;BuildSystem.Reset();Stage(site);yield return Wait(1);var d=BuildSystem.Place(pc.me,BuildSystem.Compute((PieceType)shape,Feet,0,8),BuildMat.Wood);Equip("pistol");yield return Wait(5);if(d)yield return Take(id,shape==0?"Wall / window, door, half wall, reset":"Floor / quarter, half and three-quarter cuts",shape==0?EditTake(d):FloorEditTake(d));}MechanicsTopicJoin.Write(root,"editing","All supported edit forms / walls and floors",model,parts.ToArray());}
 IEnumerator FloorEditTake(Destructible d){foreach(int mask in new[]{1,3,7}){step="Open floor grid";_look=TilePoint(d,3);yield return Wait(2);_edit=true;yield return Wait(1);for(int i=0;i<4;i++)if((mask&(1<<i))!=0){_look=TilePoint(d,i);yield return Wait(.8f);_tap=true;yield return Wait(.5f);}step="Confirm cut";_edit=true;yield return Wait(4);step="Inspect and reset";_look=TilePoint(d,3);yield return Wait(2);_edit=true;yield return Wait(1);_aimTap=true;yield return Wait(3);}}
}
